struct PublisherTest : ::testing::Test, Observer {   // fixture is the double
  std::vector<std::string> seen;
  void on_event(const std::string& e) override { seen.push_back(e); }
};

TEST_F(PublisherTest, publishesOnce) {
  Publisher p{this};                                 // install the test itself
  p.change("x");
  ASSERT_EQ((std::vector<std::string>{"x"}), seen);
}
